// Content with portions generated by generative AI platform
package org.eclipse.kura.core.internal.linux.executor;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.concurrent.TimeUnit;

import org.junit.Test;

public class PumpFailureClassificationTest {

    private final OutputStream callerErrorStream = new ByteArrayOutputStream();
    private OutputStream callerOutputStream = new ByteArrayOutputStream();
    private FlushPumpStreamHandler handler;
    private InputStream source;
    private OutputStream destination;

    @Test
    public void closedProcessOutputIsNotReportedAsFailure() {
        givenHandler();
        givenUnreadableSource();
        givenCallerOutputAsDestination();

        whenPumpRuns();

        thenOutputFailuresAre(0);
        thenInputFailuresAre(0);
    }

    @Test
    public void closedProcessErrorIsNotReportedAsFailure() {
        givenHandler();
        givenUnreadableSource();
        givenCallerErrorAsDestination();

        whenPumpRuns();

        thenOutputFailuresAre(0);
        thenInputFailuresAre(0);
    }

    @Test
    public void failingCallerStreamIsReportedAsOutputFailure() {
        givenFailingCallerOutputStream();
        givenHandler();
        givenSourceWithData();
        givenCallerOutputAsDestination();

        whenPumpRuns();

        thenOutputFailuresAre(1);
        thenInputFailuresAre(0);
    }

    @Test
    public void failingProcessInputIsReportedAsInputFailure() {
        givenHandler();
        givenSourceWithData();
        givenFailingProcessInputAsDestination();

        whenPumpRuns();

        thenOutputFailuresAre(0);
        thenInputFailuresAre(1);
    }

    @Test
    public void unreadableCallerInputIsReportedAsInputFailure() {
        givenHandler();
        givenUnreadableSource();
        givenProcessInputAsDestination();

        whenPumpRuns();

        thenOutputFailuresAre(0);
        thenInputFailuresAre(1);
    }

    private void givenFailingCallerOutputStream() {
        this.callerOutputStream = new FailingOutputStream();
    }

    private void givenHandler() {
        this.handler = new FlushPumpStreamHandler(this.callerOutputStream, this.callerErrorStream, null);
    }

    private void givenUnreadableSource() {
        this.source = new InputStream() {

            @Override
            public int read() throws IOException {
                throw new IOException("Stream closed");
            }
        };
    }

    private void givenSourceWithData() {
        this.source = new ByteArrayInputStream("hello".getBytes(UTF_8));
    }

    private void givenCallerOutputAsDestination() {
        this.destination = this.callerOutputStream;
    }

    private void givenCallerErrorAsDestination() {
        this.destination = this.callerErrorStream;
    }

    private void givenProcessInputAsDestination() {
        this.destination = new ByteArrayOutputStream();
    }

    private void givenFailingProcessInputAsDestination() {
        this.destination = new FailingOutputStream();
    }

    private void whenPumpRuns() {
        Thread pump = this.handler.createPump(this.source, this.destination, false);
        pump.start();
        try {
            pump.join(TimeUnit.SECONDS.toMillis(30));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(e);
        }
        assertFalse("The pump did not finish", pump.isAlive());
    }

    private void thenOutputFailuresAre(int expected) {
        assertEquals(expected, this.handler.getOutputFailures().size());
    }

    private void thenInputFailuresAre(int expected) {
        assertEquals(expected, this.handler.getInputFailures().size());
    }

    private static final class FailingOutputStream extends OutputStream {

        @Override
        public void write(int b) throws IOException {
            throw new IOException("write failed");
        }
    }
}
